"""Weights A/B demo: fly the released official weights and the locally trained
seeds through the same Isaac scene, outside the frozen benchmark matrix.

Design notes (see docs/proposals/weights_ab_demo_design.md):

* the scene is regenerated by ``yopo_repro.forest.generate(seed)`` and is
  byte-identical to the frozen protocol map of that seed, so both arms fly the
  same obstacles, start, goal, speed and duration;
* every run is written with an explicit non-matrix scope, so the aggregator
  treats it as a diagnostic run and the 1800-slot evidence stays untouched;
* the checkpoint hash recorded inside ``metrics.json`` is authoritative; the
  human-readable ``weights`` string of the frozen runner is a default label and
  is never used as provenance for these demo runs.
"""
from pathlib import Path
import argparse
import hashlib
import json
import os
import shutil
import subprocess
import sys
import time

ROOT = Path(__file__).resolve().parents[1]
SCOPE = 'weights_ab_demo_not_matrix'
DEFAULT_ARMS = {
    'official':{'checkpoint':'official_epoch50_reference/best_policy.pth',
                'source':'YOPO-Simple released epoch50 (renamed to main layout, values unchanged)'},
    'seed0':{'checkpoint':'formal_main_v1_seed0/best_policy.pth','source':'local formal 50-epoch run, audited'},
    'seed1':{'checkpoint':'formal_main_v1_seed1/best_policy.pth','source':'local formal 50-epoch run, audited'},
    'seed2':{'checkpoint':'formal_main_v1_seed2/best_policy.pth','source':'local formal 50-epoch run, audited'},
}
OFFICIAL_REFERENCE = 'checkpoints/official_epoch50_reference'


def sha256_file(path):
    return hashlib.sha256(Path(path).read_bytes()).hexdigest()


def ensure_official_reference():
    """Stage the renamed official weights inside checkpoints/ (runner requirement)."""
    target = ROOT/OFFICIAL_REFERENCE/'best_policy.pth'
    source = ROOT/'artifacts/expert/official_epoch50_policy_layout.pth'
    mapping = json.loads((ROOT/'artifacts/expert/official_checkpoint_mapping.json').read_text(encoding='utf-8'))
    if not target.is_file():
        if not source.is_file():
            raise SystemExit('mapped official checkpoint missing: %s'%source)
        target.parent.mkdir(parents=True,exist_ok=True)
        shutil.copy2(source,target)
    provenance = {'scope':'reference weights for the weights A/B demo; NOT a from-scratch audited run and never valid as matrix evidence',
                  'source_repository':'TJU-Aerial-Robotics/YOPO (branch YOPO-Simple)',
                  'source_commit':mapping.get('source_commit','bd8a7f91953cfef9f1aa9a48d7ff0ab7bceee132'),
                  'source_checkpoint':mapping['source_checkpoint'],'source_sha256':mapping['source_sha256'],
                  'rename_only':True,'renamed_keys':mapping['renamed_keys'],
                  'staged_checkpoint':str(target.relative_to(ROOT)),'staged_sha256':sha256_file(target),
                  'mapping_record':'artifacts/expert/official_checkpoint_mapping.json',
                  'recorded_at':time.strftime('%Y-%m-%dT%H:%M:%S%z')}
    (target.parent/'PROVENANCE.json').write_text(json.dumps(provenance,indent=2,ensure_ascii=False)+'\n',encoding='utf-8')
    # The planner container requires a run_manifest.json next to the checkpoint and
    # checks its profile/trajectory against the runtime config. Reuse the audited
    # seed0 manifest's profile/trajectory blocks (same configs) but make the run
    # identity unmistakably non-audited, so this directory can never pass
    # verify_formal_yopo_checkpoint().
    template = json.loads((ROOT/'checkpoints/formal_main_v1_seed0/run_manifest.json').read_text(encoding='utf-8'))
    manifest = {'seed':None,'epochs':None,'batch_size':None,'device':'cuda',
                'profile':template['profile'],'trajectory':template['trajectory'],
                'dataset_sha256':None,'code_sha256':None,'torch':template.get('torch'),
                'train_samples':None,'valid_samples':None,'validation_state_seed':None,
                'initial_model_sha256':None,
                'initialization':'official YOPO-Simple released epoch50 weights, renamed to the main-branch layout; not a from-scratch run',
                'dataset_path':None,'status':'reference_weights_for_demo_only',
                'weights_provenance':provenance}
    (target.parent/'run_manifest.json').write_text(json.dumps(manifest,indent=2,ensure_ascii=False)+'\n',encoding='utf-8')
    return provenance


def run_dir(name):
    return ROOT/'artifacts/ros2_flights'/name


def collect(name):
    metrics = json.loads((run_dir(name)/'metrics.json').read_text(encoding='utf-8'))
    keep = ['status','backend','device','checkpoint_sha256','identity_sha256','sim_duration_s','wall_runtime_s',
            'path_length_m','goal_error_m','max_speed_mps','min_net_clearance_m','real_time_factor',
            'end_to_end_wall_p50_ms','end_to_end_wall_p95_ms','frames','scope']
    record = {key:metrics.get(key) for key in keep}
    record['run'] = name
    record['flight_events'] = len(metrics.get('events') or [])
    return record


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('--arms',default='official,seed0')
    parser.add_argument('--scenes',default='5000')
    parser.add_argument('--speed',type=float,default=2.0)
    parser.add_argument('--duration',type=float,default=30.0)
    parser.add_argument('--tag',default='')
    parser.add_argument('--python',default=None,
                        help='Isaac Sim python that can import isaacsim (default: $YOPO_ISAAC_PYTHON or python on PATH)')
    parser.add_argument('--skip-existing',action='store_true')
    parser.add_argument('--dry-run',action='store_true')
    args = parser.parse_args()
    if args.python is None:args.python = os.environ.get('YOPO_ISAAC_PYTHON','python')
    arms = [arm.strip() for arm in args.arms.split(',') if arm.strip()]
    scenes = [int(value) for value in args.scenes.split(',') if value.strip()]
    for arm in arms:
        if arm not in DEFAULT_ARMS:
            raise SystemExit('unknown arm %s (known: %s)'%(arm,','.join(DEFAULT_ARMS)))
    interpreter = Path(args.python)
    if not interpreter.is_file():
        resolved = shutil.which(args.python)
        if resolved is None:
            raise SystemExit('Isaac Sim python not found: %s (set YOPO_ISAAC_PYTHON or pass --python)'%args.python)
        interpreter = Path(resolved)
    provenance = ensure_official_reference()
    summary_path = ROOT/'artifacts/weights_ab_demo/summary.json'
    manifest_path = ROOT/'artifacts/weights_ab_demo/manifest.json'
    (ROOT/'artifacts/weights_ab_demo/logs').mkdir(parents=True,exist_ok=True)
    records = []
    for scene in scenes:
        for arm in arms:
            name = 'abdemo_%s%s_m%d'%(arm,('_'+args.tag) if args.tag else '',scene)
            entry = {'run':name,'arm':arm,'scene_seed':scene,'scope':SCOPE,
                     'checkpoint':DEFAULT_ARMS[arm]['checkpoint'],'source':DEFAULT_ARMS[arm]['source'],
                     'speed_mps':args.speed,'duration_s':args.duration}
            if run_dir(name).is_dir() and args.skip_existing:
                entry['status'] = 'skipped_existing'
                entry.update({key:value for key,value in collect(name).items() if key not in entry})
                records.append(entry);continue
            command = [str(interpreter),str(ROOT/'scripts/run_ros2_navigation.py'),'--run',name,
                       '--backend','yopo','--device','cuda','--checkpoint',DEFAULT_ARMS[arm]['checkpoint'],
                       '--map-seed',str(scene),'--speed',str(args.speed),'--duration',str(args.duration),
                       '--scope',SCOPE]
            entry['command'] = ' '.join(command[1:])
            if args.dry_run:
                entry['status'] = 'dry_run'
                records.append(entry);print(json.dumps(entry,ensure_ascii=False));continue
            log = ROOT/'artifacts/weights_ab_demo/logs'/(name+'.log')
            started = time.time()
            env = os.environ.copy()
            env['OMNI_KIT_ACCEPT_EULA'] = 'YES'   # same accepted project runtime setting as the frozen pipeline
            result = subprocess.run(command,cwd=ROOT,text=True,capture_output=True,env=env)
            entry['wall_s'] = round(time.time()-started,2)
            log.write_text((result.stdout or '')+'\n'+(result.stderr or ''),encoding='utf-8')
            entry['runner_returncode'] = result.returncode
            if (run_dir(name)/'metrics.json').is_file():
                entry.update({key:value for key,value in collect(name).items() if key not in entry})
            records.append(entry)
            print(json.dumps({key:entry.get(key) for key in ('run','arm','status','wall_s','runner_returncode',
                                                             'checkpoint_sha256','sim_duration_s','path_length_m',
                                                             'goal_error_m','real_time_factor')},ensure_ascii=False))
    report = {'recorded_at':time.strftime('%Y-%m-%dT%H:%M:%S%z'),'scope':SCOPE,
              'purpose':'same-scene A/B between the released official weights and the locally trained seeds',
              'scene_equivalence':'scene is regenerated by yopo_repro.forest.generate(seed); verified byte-identical to the frozen protocol map of that seed',
              'not_matrix_evidence':'these runs are diagnostic scope; they are ignored by the frozen 1800-slot aggregation',
              'official_reference_provenance':provenance,'records':records}
    (ROOT/'artifacts/weights_ab_demo').mkdir(parents=True,exist_ok=True)
    summary_path.write_text(json.dumps(report,indent=2,ensure_ascii=False)+'\n',encoding='utf-8')
    manifest_path.write_text(json.dumps({'scope':SCOPE,'arms':{arm:DEFAULT_ARMS[arm] for arm in arms},
                                         'scenes':scenes,'speed_mps':args.speed,'duration_s':args.duration,
                                         'summary':str(summary_path.relative_to(ROOT)),
                                         'records':len(records)},indent=2,ensure_ascii=False)+'\n',encoding='utf-8')
    print(json.dumps({'summary':str(summary_path.relative_to(ROOT)),'records':len(records)},ensure_ascii=False))


if __name__ == '__main__':
    main()
